#include "settings/settings_controller.h"
#include <QGuiApplication>
#include <QPalette>
#include <QQuickView>
#include <QQmlContext>
int main(int argc, char **argv) { QGuiApplication app(argc, argv); app.setApplicationName(QStringLiteral("Modern IME 设置")); QPalette palette; palette.setColor(QPalette::Window, QColor(QStringLiteral("#111318"))); palette.setColor(QPalette::WindowText, QColor(QStringLiteral("#f4f7ff"))); palette.setColor(QPalette::Base, QColor(QStringLiteral("#10141d"))); palette.setColor(QPalette::AlternateBase, QColor(QStringLiteral("#1a1d25"))); palette.setColor(QPalette::Text, QColor(QStringLiteral("#f4f7ff"))); palette.setColor(QPalette::Button, QColor(QStringLiteral("#293247"))); palette.setColor(QPalette::ButtonText, QColor(QStringLiteral("#f4f7ff"))); palette.setColor(QPalette::Highlight, QColor(QStringLiteral("#5a8dee"))); palette.setColor(QPalette::HighlightedText, QColor(QStringLiteral("#ffffff"))); palette.setColor(QPalette::PlaceholderText, QColor(QStringLiteral("#9aa8c2"))); app.setPalette(palette); modernime::SettingsController controller; QQuickView view; view.rootContext()->setContextProperty(QStringLiteral("settings"), &controller); view.setSource(QUrl(QStringLiteral("qrc:/qml/SettingsWindow.qml"))); view.setTitle(QStringLiteral("Modern IME")); view.setResizeMode(QQuickView::SizeRootObjectToView); view.resize(1120, 720); view.show(); return app.exec(); }
